INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e32e2d20-6601-44b6-a436-0536f18595c0', '4fc4ea47-6205-4e8e-9ac9-d7ab6b2f5dc1', 0, 'An active malignant neoplasm of breast code, since the cancer history is significant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5943407a-ca42-4f85-ac39-a74c49b05380', '4fc4ea47-6205-4e8e-9ac9-d7ab6b2f5dc1', 1, 'A personal history of malignant neoplasm of breast code (Z code), since active treatment has been completed and there is no current evidence of disease — the malignancy is no longer active');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6077e118-6cf3-4b62-9351-6f99ab1aec85', '4fc4ea47-6205-4e8e-9ac9-d7ab6b2f5dc1', 2, 'An encounter for chemotherapy code, since chemotherapy was previously administered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4cfb71a1-1ead-4cab-aca5-dcb73b1b4b4a', '4fc4ea47-6205-4e8e-9ac9-d7ab6b2f5dc1', 3, 'No code may be assigned since the cancer is no longer active');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('018c4bdb-5c71-4eed-94f6-423f16b1b81e', '5c65e57f-d3c0-485d-8474-adb043106558', 0, 'The malignancy is sequenced first, followed by the encounter-for-radiotherapy code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1524fd4-f913-4c0f-8af5-c476190029fd', '5c65e57f-d3c0-485d-8474-adb043106558', 1, 'The appropriate Z code for encounter for radiotherapy is sequenced first, with the malignancy coded as an additional diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d280182-e8a8-49e8-affb-c81f52d634e5', '5c65e57f-d3c0-485d-8474-adb043106558', 2, 'Only the malignancy is coded; no Z code is ever used for radiotherapy encounters');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8caa9419-97f3-4013-b8b5-eeb16f37b900', '5c65e57f-d3c0-485d-8474-adb043106558', 3, 'Radiotherapy encounters are never separately coded from surgical treatment encounters');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c126c12-00e8-4d9b-805c-b64c218eeddb', '5b9d0d16-2188-4485-853d-ccb5ff935726', 0, 'Dilation (the vessel lumen is expanded, with a device — the stent — left in place)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80d3eb83-bda5-44ac-9e78-d005fb4b3415', '5b9d0d16-2188-4485-853d-ccb5ff935726', 1, 'Restriction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60fc2f0c-cfe4-4f38-a744-b966127b422f', '5b9d0d16-2188-4485-853d-ccb5ff935726', 2, 'Occlusion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d486789-f24f-4485-bd43-62e7606dad7e', '5b9d0d16-2188-4485-853d-ccb5ff935726', 3, 'Bypass');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c791ad8a-a0e9-4126-88a9-c46162ab27e7', '141544ab-6328-442e-86f8-58a5ab8e6faf', 0, 'Bypass (altering the route of passage of the contents of a tubular body part)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e90a0245-0c21-43bf-92fd-48d74150d7cf', '141544ab-6328-442e-86f8-58a5ab8e6faf', 1, 'Dilation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5fcd53a9-74f9-489b-922b-448b335e897f', '141544ab-6328-442e-86f8-58a5ab8e6faf', 2, 'Restriction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd2448d0-95c0-44a9-a342-4d07a596d4d3', '141544ab-6328-442e-86f8-58a5ab8e6faf', 3, 'Transfer');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8d7f52a-d901-45bc-88ab-563013135dc3', 'b462b75a-8e88-4b05-b655-825fc8d5c8d4', 0, 'NSTEMI and STEMI are coded identically with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a27bfeb-5403-4f66-90ca-ee9f742799e1', 'b462b75a-8e88-4b05-b655-825fc8d5c8d4', 1, 'ICD-10-CM classifies MI by type (STEMI vs. NSTEMI) and by the specific coronary artery/wall involved when documented, with distinct code categories/subcategories for each — using an unspecified or STEMI code for a documented NSTEMI would be inaccurate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10165510-fe32-4986-99ca-dc90e07c0446', 'b462b75a-8e88-4b05-b655-825fc8d5c8d4', 2, 'NSTEMI can never be coded as a principal diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6f66c6f-944f-4708-9d63-571fbe8fac3d', 'b462b75a-8e88-4b05-b655-825fc8d5c8d4', 3, 'Only STEMI is codeable in ICD-10-CM; NSTEMI has no corresponding code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47bebbb0-496a-4c62-87cd-7b0fc6deb404', '90bf58dd-f5ba-41bd-9a88-d23924a73c0d', 0, 'The same code as the original MI with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83c0524e-f892-4a89-b53a-584ea998125e', '90bf58dd-f5ba-41bd-9a88-d23924a73c0d', 1, 'A code from the subsequent MI category, reflecting a new AMI occurring within 4 weeks of a prior AMI, in addition to the original MI code as appropriate per guidelines');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8d70f56-28c9-40b8-bb09-4473174e2adb', '90bf58dd-f5ba-41bd-9a88-d23924a73c0d', 2, 'Only a history-of-MI code, since it''s a recurrence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f2ed559-d25c-46c5-971b-ef1eb1456ef0', '90bf58dd-f5ba-41bd-9a88-d23924a73c0d', 3, 'This scenario cannot be coded under ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b1b9a05-dce3-44b3-b8e6-361cb81b8a74', '33466491-c54c-4d08-9e14-0eacac7f20e0', 0, 'Replacement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a420318a-05c2-40d2-a7c5-8804c8f4b790', '33466491-c54c-4d08-9e14-0eacac7f20e0', 1, 'Insertion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('768c074e-e362-497e-bd87-660d1fdc71ce', '33466491-c54c-4d08-9e14-0eacac7f20e0', 2, 'Supplement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9c6739a-4916-428b-958d-1c1bc5a52334', '33466491-c54c-4d08-9e14-0eacac7f20e0', 3, 'Repair');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('112108a6-36f0-4cb9-b702-bdb18166562b', '170f4cb1-e75a-42f9-9255-df59b2cd6414', 0, 'Reposition (for realigning the bone fragments) and Insertion (for the internal fixation device, if it doesn''t itself replace or reinforce a body part)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4143481-c59f-46c6-bd72-c1f827d7ea67', '170f4cb1-e75a-42f9-9255-df59b2cd6414', 1, 'Only Excision, since bone is involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b5daa27-2da6-438e-ae73-f716172820ea', '170f4cb1-e75a-42f9-9255-df59b2cd6414', 2, 'Only Removal, since hardware is being placed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09c8b33b-1707-46d9-91fc-aa57b08e6a44', '170f4cb1-e75a-42f9-9255-df59b2cd6414', 3, 'Only Supplement, since hardware reinforces the bone');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebe1f584-cfa0-4b06-8317-ff1e55381575', 'cf045b7f-33d7-4e41-b8cf-bd5b8e270c51', 0, 'A combination code (where available) or the appropriate COPD code capturing both the chronic condition and the acute exacerbation, since ICD-10-CM classifies COPD with acute exacerbation as a more specific code than COPD alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3b94978-7bdf-4675-829a-33b0b0a2ce8f', 'cf045b7f-33d7-4e41-b8cf-bd5b8e270c51', 1, 'Only the code for acute bronchitis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d25bab00-64eb-4a2c-b667-34952e14e912', 'cf045b7f-33d7-4e41-b8cf-bd5b8e270c51', 2, 'Two entirely separate, unrelated codes with no combination logic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b120b32-266e-4ba7-8ed2-b4c5ccb129d1', 'cf045b7f-33d7-4e41-b8cf-bd5b8e270c51', 3, 'The exacerbation is never separately captured in ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f00edea-5b27-432f-8ebe-622ce0bd9d8b', 'c3541ccb-4a4f-45fb-9795-6bf62f74338a', 0, 'HCCs are a completely separate code set from ICD-10-CM used only in dentistry');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3a3c5d7-33fb-438c-93f3-44e3b08fba0a', 'c3541ccb-4a4f-45fb-9795-6bf62f74338a', 1, 'HCCs are risk-adjustment categories that CMS maps specific ICD-10-CM diagnosis codes into, used to predict expected healthcare costs (particularly for Medicare Advantage and other risk-adjusted payment models) — meaning coding accuracy and completeness for HCC-relevant diagnoses has direct payment/risk-score implications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bec05557-acb2-4fac-b91d-7dfed4c29eca', 'c3541ccb-4a4f-45fb-9795-6bf62f74338a', 2, 'HCCs apply only to inpatient DRG-based reimbursement, never risk-adjusted payment models');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87465d7e-0bcd-4a0a-beab-529ef7799a4e', 'c3541ccb-4a4f-45fb-9795-6bf62f74338a', 3, 'HCCs are determined solely by patient age, unrelated to any diagnosis coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('022bd9a5-c2e5-43e5-a870-60cd71c8f39e', '0dfcc6f3-6fb1-4d84-802a-6a74feb2e1c4', 0, 'HCC risk scores are permanent and never need re-documentation once initially captured');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('51844811-ede8-417a-b6bc-4d9df05f20df', '0dfcc6f3-6fb1-4d84-802a-6a74feb2e1c4', 1, 'Risk-adjustment models generally reset annually, meaning a chronic HCC-relevant condition not addressed/documented and coded again within the current calendar year may not continue to be reflected in that year''s risk score/expected cost calculation, even though the patient still has the condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca0f280b-6fe8-4b8e-911c-8cfdc24e51a3', '0dfcc6f3-6fb1-4d84-802a-6a74feb2e1c4', 2, 'Recapture only applies to conditions that have worsened since the prior year');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64ca6a59-e17b-4be2-bdc0-d8b0f6719db5', '0dfcc6f3-6fb1-4d84-802a-6a74feb2e1c4', 3, 'HCC recapture is a billing myth with no basis in actual CMS risk-adjustment methodology');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7684557b-c89a-456c-9c12-5393a0368dcb', 'd4c7017b-fe78-4e6e-98ed-fc040500c5e1', 0, 'Code only diabetes, unspecified, since it''s simpler');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('984a8bff-f420-497b-9251-8cac2e69a46c', 'd4c7017b-fe78-4e6e-98ed-fc040500c5e1', 1, 'Code the specific combination code for type 2 diabetes with diabetic polyneuropathy, since it is both clinically accurate and, given it is HCC-relevant, must be specifically and accurately captured (not under-coded to unspecified diabetes) to correctly reflect the patient''s risk profile for this year');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cac96202-8d46-4e46-b3d9-88ca138b79bc', 'd4c7017b-fe78-4e6e-98ed-fc040500c5e1', 2, 'HCC-relevant diagnoses should never be coded to their most specific level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2965357f-50dc-414b-9de3-4b2dd38af3b3', 'd4c7017b-fe78-4e6e-98ed-fc040500c5e1', 3, 'Only the neuropathy is coded, with diabetes omitted entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('640fbd18-d870-4ec1-b174-3f198475af50', '3137d9f1-cd88-4d18-b582-a74e98d74a4b', 0, 'The Two-Midnight Rule, which generally presumes inpatient admission is appropriate (rather than outpatient/observation status) when the physician expects the patient''s care to span at least two midnights');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13905c6c-26ac-43b5-9a79-b84d25c6a7c1', '3137d9f1-cd88-4d18-b582-a74e98d74a4b', 1, 'The HCC risk-adjustment model');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79bfaac0-7456-4019-86e9-3a25c3cdd5bf', '3137d9f1-cd88-4d18-b582-a74e98d74a4b', 2, 'The NCCI Procedure-to-Procedure edit framework');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20133d6d-838f-45fb-b832-cb9081ae96c1', '3137d9f1-cd88-4d18-b582-a74e98d74a4b', 3, 'The HITECH breach notification rule');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1daff8f-7e3b-435d-9b31-1000afb15996', '6282297a-0372-40b9-bbf4-89d4b128cebd', 0, 'It has no relevance whatsoever to coding or HIM staff');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('495fd3ab-37be-435a-a69a-155391bb6f90', '6282297a-0372-40b9-bbf4-89d4b128cebd', 1, 'Coders/HIM staff should understand it as context for why admission status (inpatient vs. observation/outpatient) was assigned, since that status affects which coding/billing rules (UHDDS/DRG vs. outpatient guidelines) apply to the encounter, and inconsistent status-vs-documentation can itself be a compliance/documentation-integrity flag');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b4a679c-20a5-4854-aa6e-8b4814e2ec4b', '6282297a-0372-40b9-bbf4-89d4b128cebd', 2, 'The Two-Midnight Rule determines which specific ICD-10-CM code is assigned as principal diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('722b2087-0011-421a-8fc2-ee5356780cb4', '6282297a-0372-40b9-bbf4-89d4b128cebd', 3, 'The Two-Midnight Rule replaces the need for POA indicator assignment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb74d53d-53c9-41c6-96eb-94129a7ee8ce', 'f1a299b6-bc23-49fa-be00-15dd0958f3e0', 0, 'Never coded under any circumstance during this admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c941189b-7ee8-457d-88e3-ec4019735159', 'f1a299b6-bc23-49fa-be00-15dd0958f3e0', 1, 'Coded as an additional diagnosis if it meets UHDDS''s additional-diagnosis criteria for this stay (e.g., medication continuation/monitoring that is clinically relevant to perioperative management) — routine, unaddressed chronic conditions with no clinical impact on this specific stay would not automatically qualify');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('087f3230-604f-40c4-9d78-825bd6692516', 'f1a299b6-bc23-49fa-be00-15dd0958f3e0', 2, 'Always coded as the principal diagnosis regardless of the reason for admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6b11b46-8399-460b-954e-db9b40c0bf07', 'f1a299b6-bc23-49fa-be00-15dd0958f3e0', 3, 'Coded only if the patient specifically requests it be documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f3c03d2-b3ed-4bdd-b897-954c7ddb1a1f', '21c68f90-26b9-4896-acd6-5752bf092ce7', 0, 'Only the chronic form is ever coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e35ce1dd-092c-41aa-850e-8ed1841d41ca', '21c68f90-26b9-4896-acd6-5752bf092ce7', 1, 'ICD-10-CM generally provides — and the guidelines direct using — a combination code capturing both the acute and chronic nature together, when such a combination code exists for that condition (as with heart failure), rather than reporting the acute and chronic forms as two separate, unrelated codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0e34c88-0e04-4271-ab4f-4cde18ddbe31', '21c68f90-26b9-4896-acd6-5752bf092ce7', 2, 'Only the acute form is ever coded, with the chronic form disregarded entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b5164df-a39a-4b8b-be2c-2abc2ba8b92a', '21c68f90-26b9-4896-acd6-5752bf092ce7', 3, 'Acute and chronic combination coding does not exist anywhere in ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3755039f-4e7c-499f-b7dd-6719c22be197', '7eb990b0-14b8-49eb-be4f-29219bd0a1a0', 0, 'The diagnostic catheterization/angiography procedure itself is coded per its own ICD-10-PCS code(s) (reflecting the imaging/measurement procedures actually performed), with no bypass/dilation code assigned since no therapeutic intervention occurred at this encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9999328-920d-4a29-bf92-d01c63276626', '7eb990b0-14b8-49eb-be4f-29219bd0a1a0', 1, 'A CABG code should automatically be assigned since multi-vessel disease was found');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52164bd2-1f35-4490-b384-1cd71d864e67', '7eb990b0-14b8-49eb-be4f-29219bd0a1a0', 2, 'No procedure code is assigned since it was ''only diagnostic''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2cd9f7d-6193-48b5-9f7c-de5223b72f3e', '7eb990b0-14b8-49eb-be4f-29219bd0a1a0', 3, 'The same code used for angioplasty is used regardless of whether intervention occurred');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a1aa677-d30d-4637-af2c-ec5819ab0044', '31ba5c23-ce10-4842-98c7-3dfa9f8010fd', 0, 'A documentation gap requiring an automatic query regardless of the clinical support already present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c76eda6-576e-4c20-81c3-81c5aaf4a60b', '31ba5c23-ce10-4842-98c7-3dfa9f8010fd', 1, 'An adequately supported, specific diagnosis appropriately codeable to its documented severity level, since sufficient clinical indicators (BMI, weight loss, dietitian assessment) support the severity as documented — consistent with the earlier-established BMI/dietitian-documentation exception discussed for similar scenarios');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e6fb3fc-f8e6-4e36-9810-aae984db6d02', '31ba5c23-ce10-4842-98c7-3dfa9f8010fd', 2, 'A diagnosis that can never be coded because a dietitian, not a physician, performed the nutritional assessment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2d3cc40-8ecf-45bd-b1f0-d27778cfe77a', '31ba5c23-ce10-4842-98c7-3dfa9f8010fd', 3, 'Something that must default to the unspecified malnutrition code regardless of supporting documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85b02658-7941-4319-81de-8126d550ae2d', 'b4af6d39-f022-4950-80f4-8cfff0af1938', 0, 'The new acute stroke and any residual sequela of the OLD stroke are both coded as appropriate for the current clinical picture — an old, resolved sequela and a brand-new acute event are not mutually exclusive and are coded according to their own respective guidelines (sequela coding for the old residual, acute stroke coding for the new event)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cef27597-59b0-4298-9b18-d5437031edcd', 'b4af6d39-f022-4950-80f4-8cfff0af1938', 1, 'Only the new acute event may ever be coded; old sequelae are always dropped once a new acute event occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e62fa6b-eee6-4885-89c9-9b6c84083f0e', 'b4af6d39-f022-4950-80f4-8cfff0af1938', 2, 'The two must always be combined into a single code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc150d1b-2681-43af-a8f2-4b9ccdecbeab', 'b4af6d39-f022-4950-80f4-8cfff0af1938', 3, 'Sequela codes automatically expire after one year and can never be used again after that');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce70eb9d-8b7f-46e7-b247-61940df6b8dd', 'fb29257e-b3e4-4d47-985f-c408749ed17e', 0, 'Using the unspecified acute pancreatitis code, since etiology documentation doesn''t affect code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66347584-e56b-4aad-a57f-9f8619d3ac0f', 'fb29257e-b3e4-4d47-985f-c408749ed17e', 1, 'Using the ICD-10-CM code specifically capturing biliary/gallstone-related acute pancreatitis, if the classification provides a more specific option, rather than defaulting to an unspecified or idiopathic code when a clear etiology is actually documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b358e474-d9fd-451d-b9c7-f532da07cecc', 'fb29257e-b3e4-4d47-985f-c408749ed17e', 2, 'Coding it as chronic pancreatitis instead, since gallstones are a chronic risk factor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c9a745f-0b33-426d-a5c8-8937a0072056', 'fb29257e-b3e4-4d47-985f-c408749ed17e', 3, 'Querying is always mandatory even when etiology is already clearly documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7623e8d0-59e8-4f33-b544-4e94d9c18be4', 'd6d4646b-bd63-459e-b079-8dac7bb42259', 0, 'Root operation Resection (the entire appendix is removed), approach percutaneous endoscopic (laparoscopic), body part appendix');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61d425ca-2623-4ee4-8e9d-bf78d8c988aa', 'd6d4646b-bd63-459e-b079-8dac7bb42259', 1, 'Root operation Excision, approach open, body part appendix');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ae24e7d-3e0f-4eb9-8aa9-1d59d81de399', 'd6d4646b-bd63-459e-b079-8dac7bb42259', 2, 'Root operation Extraction, approach external, body part appendix');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9024437-bedb-4e23-b207-d08bb35276cd', 'd6d4646b-bd63-459e-b079-8dac7bb42259', 3, 'Root operation Destruction, approach via natural orifice');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6ecf57d-0703-4b4c-8f62-b52fcdbe73fb', '10283c8d-4da4-4dcd-a34a-409f273f421d', 0, 'Detachment (cutting off all or a portion of the upper or lower extremities)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b68eb868-45f1-4645-bb15-3a937d52bfcd', '10283c8d-4da4-4dcd-a34a-409f273f421d', 1, 'Excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a63fd42-a0e6-4b4e-a0b8-15a9cd1020c5', '10283c8d-4da4-4dcd-a34a-409f273f421d', 2, 'Resection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('583d51ae-f648-4d8b-b423-d86746e7b8ed', '10283c8d-4da4-4dcd-a34a-409f273f421d', 3, 'Release');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62f9cd06-1afd-4d9e-8bbf-0d2b15b14a93', '81640577-ec03-4f98-94c0-648e150d9a62', 0, 'The acute condition (cholecystitis) is coded as principal diagnosis (assuming it meets the UHDDS definition for this admission), with the cholecystectomy coded as the principal procedure, since UHDDS principal diagnosis selection is based on the reason for admission, not automatically on whether a procedure was performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('060cd6c2-e7bf-41db-89d2-f0a7be289615', '81640577-ec03-4f98-94c0-648e150d9a62', 1, 'The procedure code always determines/overrides the principal diagnosis selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62f5613e-97fc-47a4-bddf-574fd89d5c3e', '81640577-ec03-4f98-94c0-648e150d9a62', 2, 'Only the procedure is coded; the underlying diagnosis is never separately coded when surgery is performed for it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('986bbff0-450b-4805-9e3f-0ec03e99061b', '81640577-ec03-4f98-94c0-648e150d9a62', 3, 'The two must always be combined into a single procedure-plus-diagnosis code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e481e0d8-5009-465b-8bce-e01890b3eea3', '7b9d346c-3707-47b7-b805-d7fc612f7ce6', 0, 'ESRD is coded as an additional diagnosis when it meets the UHDDS additional-diagnosis criteria for this stay (e.g., ongoing dialysis management during the admission), reflecting its ongoing clinical significance, and the specific CKD stage 5/ESRD code (not an unspecified CKD code) should be used when documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c740c07-855a-487c-a839-fd8347391a4b', '7b9d346c-3707-47b7-b805-d7fc612f7ce6', 1, 'ESRD is never coded during an unrelated admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e836e869-c3c2-41ce-8dfc-b065bee0959e', '7b9d346c-3707-47b7-b805-d7fc612f7ce6', 2, 'ESRD is always coded as the principal diagnosis regardless of the reason for admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cca9d4e3-cf80-4753-b2c5-ba035510da1c', '7b9d346c-3707-47b7-b805-d7fc612f7ce6', 3, 'Dialysis status has no bearing on which CKD-stage code is selected');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ecd8b80-7391-44f4-9104-93283da1b27f', '5f83aba7-e322-491d-a46b-c92bd2bb361c', 0, 'Excision (removing a portion of the stomach, not all of it)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d714293-9fa7-43ab-9a01-d6c4de7b49d2', '5f83aba7-e322-491d-a46b-c92bd2bb361c', 1, 'Resection (since it is bariatric surgery)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2d2fbca-4cb5-4fe9-8c48-5edf20926e5f', '5f83aba7-e322-491d-a46b-c92bd2bb361c', 2, 'Restriction only, with no tissue removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3e5fa1d-f6ee-4d35-9f62-b82c5712a409', '5f83aba7-e322-491d-a46b-c92bd2bb361c', 3, 'Destruction, since tissue is eliminated');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3fb13728-720e-40e8-8c8e-2b27caf6bee8', '7e911bfb-3768-4469-b669-6e55acb00f57', 0, 'Restriction (altering the diameter of a tubular body part without taking out or replacing any of it)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3ac7f06-d053-4896-b431-2135b70aea78', '7e911bfb-3768-4469-b669-6e55acb00f57', 1, 'Excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49aff932-4c54-40e8-853e-7d1387e1d618', '7e911bfb-3768-4469-b669-6e55acb00f57', 2, 'Resection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80c610f0-6d58-409f-b35a-60a17809300f', '7e911bfb-3768-4469-b669-6e55acb00f57', 3, 'Supplement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('056f18b3-76ec-432d-817d-665562362396', '34fb1687-5ca6-4dce-a988-82aa5c1800a5', 0, 'An active DVT code, since anticoagulation is ongoing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6e66656-9f45-41ef-9294-693db4573a82', '34fb1687-5ca6-4dce-a988-82aa5c1800a5', 1, 'A personal history of DVT/pulmonary embolism Z code, since the acute clot has resolved and the patient is in a maintenance/prevention phase of care — the ongoing anticoagulation itself may also be separately reflected (e.g., via a long-term drug therapy Z code) as clinically relevant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a8bc85b-861e-4671-836c-f30a0b60c241', '34fb1687-5ca6-4dce-a988-82aa5c1800a5', 2, 'No code at all, since the condition has resolved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9df55d6-0b0f-4c96-9aec-bc059cfa105d', '34fb1687-5ca6-4dce-a988-82aa5c1800a5', 3, 'The same code as an active DVT regardless of resolution status');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8e6935a-659a-4207-abfb-4e21b600e43d', '804eef4c-1461-421e-a08a-0c762d5985ed', 0, 'DNR status is always coded as a principal diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d11ba805-74fe-4f82-8a75-06207e9e3a6d', '804eef4c-1461-421e-a08a-0c762d5985ed', 1, 'ICD-10-CM includes a specific Z code category for documenting the presence of DNR status/advance directives when clinically relevant to the encounter, though this Z code reflects a status/circumstance rather than a diagnosis driving clinical treatment decisions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5893171b-fa1d-46a0-bea1-dfef72465eae', '804eef4c-1461-421e-a08a-0c762d5985ed', 2, 'DNR status can never be coded under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('806216bc-666b-4285-adb4-21bbe00cf2d8', '804eef4c-1461-421e-a08a-0c762d5985ed', 3, 'DNR status is coded using the same codes as a terminal illness diagnosis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d41a80ba-f195-4311-904b-f0c70c13d286', '3fc2eb06-fa74-425b-8e40-f49b3a09da76', 0, 'The atrial fibrillation itself, since its management (anticoagulation bridging) is being actively addressed during this admission, meeting UHDDS''s clinical-management criteria for an additional diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3488fbcf-9feb-48c4-9352-b290483577b7', '3fc2eb06-fa74-425b-8e40-f49b3a09da76', 1, 'Nothing related to atrial fibrillation should ever be coded during an unrelated surgical admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('821263c4-d9bf-40a1-9d70-16af240bbdbf', '3fc2eb06-fa74-425b-8e40-f49b3a09da76', 2, 'Only the surgical diagnosis may be coded; all chronic conditions are automatically excluded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8a4c5a3-39c6-44be-a2bb-c53bc4382ad4', '3fc2eb06-fa74-425b-8e40-f49b3a09da76', 3, 'Atrial fibrillation can only be coded if it is the principal diagnosis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e76bab24-3472-4695-bf47-b8800d14fa99', '818d367d-cac2-4a45-9f7b-8031cddc685b', 0, 'They are identical and interchangeable terms');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('280ef992-f7a8-4b02-95f7-075b2506b8f1', '818d367d-cac2-4a45-9f7b-8031cddc685b', 1, 'Percutaneous involves entry by puncture or minor incision to reach the site of the procedure (without visualization), while percutaneous endoscopic involves the same type of entry but with the additional use of a scope/camera to visualize the procedure site');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09f2f8bd-4275-4575-bd63-dc94ace03830', '818d367d-cac2-4a45-9f7b-8031cddc685b', 2, 'Percutaneous endoscopic never involves any incision or puncture at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60c03c37-035a-42e3-a597-4c4dd83d8049', '818d367d-cac2-4a45-9f7b-8031cddc685b', 3, 'Percutaneous applies only to cardiac procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f49846a-4dbd-4bea-afde-8d21c01b1ba3', '1034fbfc-31e6-46aa-9416-8d1674bab010', 0, 'Entry into the body occurs through a natural orifice (e.g., mouth, vagina) or a pre-existing artificial opening (e.g., an established stoma), without cutting through skin/mucous membrane');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('769d3d1a-10c1-4581-aefa-36fdbb4859ce', '1034fbfc-31e6-46aa-9416-8d1674bab010', 1, 'This approach always requires an incision through the skin');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b24b6698-93d9-4a85-bd0a-441246becbbe', '1034fbfc-31e6-46aa-9416-8d1674bab010', 2, 'This approach applies only to cardiac catheterization procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ea7528d-0c97-4c7b-9dda-abdbef5239f1', '1034fbfc-31e6-46aa-9416-8d1674bab010', 3, 'This approach is identical to the open approach');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef747f34-4572-4033-8355-04659044de5d', 'c1a0a699-84b3-43f2-b049-1f9f5532a92d', 0, 'Both procedures are always coded using only the initial approach, regardless of what was actually completed for the therapeutic portion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d57e1e88-a1fe-4446-8ba1-634f0b253709', 'c1a0a699-84b3-43f2-b049-1f9f5532a92d', 1, 'Coding should reflect the approach actually used for each distinct procedure performed/completed, consistent with the general principle that a converted or changed approach is coded as what was actually done — the same conversion logic already discussed applies whether the change happens mid-single-procedure or between a diagnostic and a subsequent therapeutic procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44f29c34-1889-49a3-a4b4-59e3b277ad54', 'c1a0a699-84b3-43f2-b049-1f9f5532a92d', 2, 'Only the therapeutic procedure may ever be coded, with the diagnostic portion never separately considered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('494fa016-8a70-455a-9060-c091a2884a77', 'c1a0a699-84b3-43f2-b049-1f9f5532a92d', 3, 'Approach is never a coding consideration when multiple procedures occur in the same session');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a871b039-99b2-4eb8-a96c-cdaa2b97b44a', 'a8b16097-3f54-4bda-bf8b-e4515747bf30', 0, 'Extraction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b97fa34d-be4a-4096-954e-57108adcfb4a', 'a8b16097-3f54-4bda-bf8b-e4515747bf30', 1, 'Excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d86ff7a-38ff-4065-b66a-3ea89f304896', 'a8b16097-3f54-4bda-bf8b-e4515747bf30', 2, 'Fragmentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce5f922e-f627-4a90-8773-8530c1a802b6', 'a8b16097-3f54-4bda-bf8b-e4515747bf30', 3, 'Drainage');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('691878cf-db05-427c-b512-10d9f2ff1b71', 'bed3bbda-5647-4f69-8d56-cc597e89c743', 0, 'Only the anatomic site, with stage never being a coding factor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0df92249-418a-4431-9eac-886e406daf04', 'bed3bbda-5647-4f69-8d56-cc597e89c743', 1, 'Both the anatomic site AND the stage (unstageable, stage 1 through 4, or deep tissue pressure injury) of the pressure ulcer, since ICD-10-CM''s pressure ulcer codes are structured by site-and-stage combination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1440e5a4-2296-4330-b0f7-9df069d27bd5', 'bed3bbda-5647-4f69-8d56-cc597e89c743', 2, 'Only whether the ulcer is present, with no further detail ever coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('287c0a65-4e22-442c-8f7f-8e6799f05707', 'bed3bbda-5647-4f69-8d56-cc597e89c743', 3, 'Pressure ulcer coding requires a surgical biopsy before any code may be assigned');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2dec1727-166d-4b33-a132-0c0883dfc00a', '3ab62432-1221-4ae9-9b06-091b7a2b1633', 0, 'Only the highest stage ever reached during the stay is coded, since ICD-10-CM guidance directs coding the highest stage documented for that site during the episode of care when progression is documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa6aeb37-7899-40b5-92e9-866b34d880b1', '3ab62432-1221-4ae9-9b06-091b7a2b1633', 1, 'Only the admission stage is ever coded, regardless of progression');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9c93bf0-4d21-497e-aac5-64d88cc2c0bf', '3ab62432-1221-4ae9-9b06-091b7a2b1633', 2, 'Both stages must be coded as two entirely separate, unrelated ulcers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('927d7cf7-13c8-4ee5-940e-1513306bd34a', '3ab62432-1221-4ae9-9b06-091b7a2b1633', 3, 'Pressure ulcer staging progression can never be coded under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6370cd4b-d567-482f-ba4b-544ac34760a7', 'e4b8e55d-3692-4f00-bca0-8b8831094655', 0, 'A combination code reflecting the specific sickle cell disease type WITH the crisis (e.g., ''with crisis'' or ''with vaso-occlusive pain''), when the classification provides that combination, rather than coding sickle cell disease and the crisis as unrelated codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49c12c8a-b4e7-46d7-b6ac-df9f2f5fc554', 'e4b8e55d-3692-4f00-bca0-8b8831094655', 1, 'Only a generic ''pain, unspecified'' code, with sickle cell disease never coded during a crisis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fcb6e97-5739-41bc-9e7e-7cecbaab3c30', 'e4b8e55d-3692-4f00-bca0-8b8831094655', 2, 'Sickle cell crisis is never separately identified in ICD-10-CM from the base disease code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab353606-44ab-4851-8d9f-98941ceeed35', 'e4b8e55d-3692-4f00-bca0-8b8831094655', 3, 'Coding requires genetic testing confirmation before any sickle cell code may be used, regardless of a prior established diagnosis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('836940c0-ca71-4ddc-9ae9-848d8160786c', 'ae6c1e5c-3286-4d60-a5fb-81ce6d03a8a7', 0, 'Multiple codes are never used for a single underlying condition under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0199b64-9efb-430f-923d-e889db430207', 'ae6c1e5c-3286-4d60-a5fb-81ce6d03a8a7', 1, 'Some conditions require reporting more than one code to fully capture the condition (e.g., an underlying etiology code plus a manifestation code, per ''code first''/''use additional code'' conventions already discussed), representing a deliberate classification design choice rather than a coding error');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4406f681-3ff8-4871-a512-5751c7190cf3', 'ae6c1e5c-3286-4d60-a5fb-81ce6d03a8a7', 2, 'Multiple coding always indicates a coder mistake requiring correction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20f78ccb-4894-4839-81ec-58f0d9a9f1cc', 'ae6c1e5c-3286-4d60-a5fb-81ce6d03a8a7', 3, 'Multiple coding applies only to procedure codes, never diagnosis codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f47c6e0-9e09-4062-b30c-b1c9e956068c', '64c6a615-70dc-405c-9f67-6c870cc47f3c', 0, 'Using the specific ARDS code, with the underlying cause/associated trauma also coded per applicable guidelines, rather than coding only a generic respiratory failure code when ARDS is specifically documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('033c8f3a-bb0f-4fe2-96ae-892df25a470e', '64c6a615-70dc-405c-9f67-6c870cc47f3c', 1, 'Using only a generic pneumonia code regardless of the ARDS diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46c1eb6d-c812-4da4-b368-ceb0d785c263', '64c6a615-70dc-405c-9f67-6c870cc47f3c', 2, 'ARDS is never separately coded from its underlying cause');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a52f8a8-5467-4cb6-8595-5ee453cc242a', '64c6a615-70dc-405c-9f67-6c870cc47f3c', 3, 'Only the trauma injury codes are used, with no respiratory code at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f891ddfd-7b72-4331-8f62-602f95e704d1', '408016d0-56f3-4c76-978c-fb3bcb98d0aa', 0, 'Excisional debridement involving muscle would generally be coded using the Excision root operation with the muscle body part value (reflecting the deepest tissue layer actually debrided), consistent with the general ICD-10-PCS principle of coding to the deepest/most extensive tissue plane involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4dca49a-49e1-4a2e-b515-bb12573f1f4b', '408016d0-56f3-4c76-978c-fb3bcb98d0aa', 1, 'Debridement is never separately coded in ICD-10-PCS regardless of depth');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5288c9e2-e743-4209-aeb4-18b9175c085b', '408016d0-56f3-4c76-978c-fb3bcb98d0aa', 2, 'All debridements are coded identically regardless of depth using a single universal code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a59b40e-0334-4680-84bb-3f98327160ff', '408016d0-56f3-4c76-978c-fb3bcb98d0aa', 3, 'Only non-excisional (mechanical) debridement can ever be coded in ICD-10-PCS');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc4fe3f4-e33a-47e7-8fb6-47399a1e2be3', 'd10ac9e8-a2b3-4f93-b819-480081d07d1d', 0, 'ICD-10-CM classifies hypertension primarily by type (e.g., essential, secondary, with heart/kidney involvement) rather than by the older severity-descriptor terms like ''malignant/benign'' hypertension, which no longer have distinct code assignments the way they did in some older classification systems — a coder should code to the hypertension type actually reflected in current documentation/classification structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a037bd0e-d025-48f8-a853-945334484813', 'd10ac9e8-a2b3-4f93-b819-480081d07d1d', 1, 'Malignant hypertension is coded identically to a malignant neoplasm');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6e762d6-6e46-47fe-8c8e-c3ef89f072f5', 'd10ac9e8-a2b3-4f93-b819-480081d07d1d', 2, 'Malignant hypertension can never be coded under ICD-10-CM');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15a94fc4-a53e-4f66-b4e2-67dcd82d5d69', 'd10ac9e8-a2b3-4f93-b819-480081d07d1d', 3, 'Only benign hypertension exists as a codeable concept in ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55395e40-a6c6-415f-9db4-faa2ae51d7fb', '7e7f13f6-92ca-4c06-b768-49fa9ccdde66', 0, 'Ignore the echo report and code only unspecified heart failure, since the physician note alone doesn''t specify type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('263a6d60-bc7f-4948-9098-5778c8facb85', '7e7f13f6-92ca-4c06-b768-49fa9ccdde66', 1, 'Recognize that clinical data elsewhere in the record (the echo report) may support greater specificity, and consider whether the physician''s own clinical documentation (not just a coder''s independent interpretation of a raw test result) supports coding to that specificity, querying if it remains genuinely unclear whether the physician agrees with connecting the echo finding to an active heart failure diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('990d14b2-1f14-4349-8dac-9ec08e6cc003', '7e7f13f6-92ca-4c06-b768-49fa9ccdde66', 2, 'Code directly from the echo report''s technical findings as if it were the physician''s own diagnostic statement, without regard to whether the physician''s own note supports that connection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae532bc9-d783-4660-b7d2-70544e940bf3', '7e7f13f6-92ca-4c06-b768-49fa9ccdde66', 3, 'Never consider ancillary test reports when coding diagnoses');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13188094-677e-4d46-8277-328d1b3acd87', 'c5f1944c-a354-49bf-9f63-60a282c8d6d0', 0, 'Assume every condition ever listed on a problem list qualifies for HCC capture regardless of whether it was addressed at the current encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6a6a235-0ab1-4b99-a810-1616175020bb', 'c5f1944c-a354-49bf-9f63-60a282c8d6d0', 1, 'Verify that HCC-relevant diagnoses are genuinely addressed/evaluated at the specific encounter (consistent with the encounter''s own documentation, not simply copied from a prior year''s problem list) before including them in that encounter''s coding, since accurately reflecting what was actually assessed matters both clinically and for risk-adjustment integrity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('302ab7dc-2cd3-4254-82fd-64a50a907b20', 'c5f1944c-a354-49bf-9f63-60a282c8d6d0', 2, 'HCC-relevant diagnoses require no documentation verification since they are pre-approved by the payer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62db633a-176c-4fc7-a425-f99b090e4146', 'c5f1944c-a354-49bf-9f63-60a282c8d6d0', 3, 'Only physicians, never any HIM/coding staff, should ever review HCC-relevant documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2e0ab9e-ca42-4ad1-aba4-a9ea1a58443d', '4fefb488-1249-40ab-b9a5-c555563aa962', 0, 'A documentation/status consistency question worth reviewing — since the actual course of the stay differed substantially from the physician''s initial expectation, understanding why (an unexpectedly rapid recovery, or a potential status-determination issue) is relevant to accurate status/UHDDS reporting, though a good-faith physician expectation at the time of the order, even if the stay didn''t ultimately reach two midnights, does not automatically make the inpatient order wrong');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0dd8206f-5dee-410d-a792-071d55f3728f', '4fefb488-1249-40ab-b9a5-c555563aa962', 1, 'This scenario always means the inpatient order was fraudulent and must be reported immediately without any further review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a0120f2-d350-45d2-865a-45787cf88537', '4fefb488-1249-40ab-b9a5-c555563aa962', 2, 'Discharge timing has no bearing on documentation review under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7fa78b8-23a8-4456-80db-4746d3d8eace', '4fefb488-1249-40ab-b9a5-c555563aa962', 3, 'The discrepancy must always be resolved by changing the diagnosis code, not the admission status');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12f950ea-cb13-434c-ae83-26aeeacc8e9b', 'c388011e-23e3-47d1-909d-7b26573da890', 0, 'Structured data received electronically from another organization is always 100% accurate and requires no clinical verification before being relied upon for coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82df706e-58fc-419b-83f3-7b21cab35374', 'c388011e-23e3-47d1-909d-7b26573da890', 1, 'Externally-sourced structured data (even when received via a standardized interoperability format) should be reviewed for clinical currency/accuracy and ideally corroborated by the receiving organization''s own clinical documentation before being relied upon for that organization''s own coding, since data accuracy at the source doesn''t guarantee continued clinical relevance for the current encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cd3ba16-6c00-4cfc-b2a9-fc09bce51127', 'c388011e-23e3-47d1-909d-7b26573da890', 2, 'HL7/FHIR-formatted data can never be used for coding under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('371a0056-43e9-4292-990c-4a601b1eae30', 'c388011e-23e3-47d1-909d-7b26573da890', 3, 'Only manually-typed documentation may ever be used for coding; structured/interoperable data is categorically excluded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17fbe0c0-0093-459e-8bda-1b9176c6f2a7', 'de0afcc3-27ec-402f-8479-abdf593fdde1', 0, 'Sufficient documentation, since the discharge summary confirms the patient did well');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98a3b119-c906-46ff-82b3-69c419c77a9f', 'de0afcc3-27ec-402f-8479-abdf593fdde1', 1, 'A significant documentation gap for procedure coding purposes — the discharge summary''s general outcome statement doesn''t substitute for the operative report''s technical details needed to assign an accurate ICD-10-PCS code, and the operative report (not the discharge summary) should be the primary source reviewed for this information');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a339549-f2f1-4f6d-a2b1-448f42ec68e0', 'de0afcc3-27ec-402f-8479-abdf593fdde1', 2, 'Proof that no procedure was actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69873f2d-b493-4e0c-8789-51a7173ab2d8', 'de0afcc3-27ec-402f-8479-abdf593fdde1', 3, 'A gap that can only be resolved by discharging and readmitting the patient');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54a80553-d87e-4d52-81f3-58c02aeca84e', '20180430-3479-4d52-a19c-c55c6c3e7213', 0, 'Code from the nursing findings alone as if they were an independent physician diagnosis of a specific heart failure type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea5e2a15-9403-453e-941b-a189a3ca5c6b', '20180430-3479-4d52-a19c-c55c6c3e7213', 1, 'Recognize that nursing clinical findings can provide useful supporting CONTEXT but do not themselves establish a physician diagnosis or its specific type — review the physician''s own documentation further for type specificity, and query if genuinely needed, rather than deriving a specific diagnosis type from nursing assessment findings alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c23ab23-2596-41e0-b2f7-abb0fb267867', '20180430-3479-4d52-a19c-c55c6c3e7213', 2, 'Ignore the nursing findings entirely as irrelevant to coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c12c65e-5bc5-4844-b265-08c18216060a', '20180430-3479-4d52-a19c-c55c6c3e7213', 3, 'Code the most severe possible heart failure type based on the symptom pattern');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec1939b2-f229-4780-bc75-8e775e5888a9', '78db5750-eecf-459d-9730-1208bbb56fd5', 0, 'Ignore the discrepancy since allergy lists are rarely accurate anyway');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ae8f5e1-e6f4-42fb-8d89-0e232ad73aba', '78db5750-eecf-459d-9730-1208bbb56fd5', 1, 'Recognize this as a patient-safety-relevant documentation-reconciliation issue that should be resolved/updated in the record (the more recent, verified reconciliation should generally govern going forward), even though allergy-list accuracy is not itself typically an ICD-10-CM coding element');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('551502e2-27f3-4472-9726-93d03b6b41de', '78db5750-eecf-459d-9730-1208bbb56fd5', 2, 'Code a new diagnosis reflecting the allergy discrepancy itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ede4cf3-efb3-4c31-9383-c0c04e628282', '78db5750-eecf-459d-9730-1208bbb56fd5', 3, 'Automatically delete the older allergy list without any reconciliation process');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97459570-3128-476b-80fb-85834a83601c', '2546e2aa-45eb-41aa-8969-1848a3cf454d', 0, 'Every chronic condition from the primary care record must always be copied into every specialist encounter''s coding regardless of relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a25a212-9933-4f01-bbf5-bef6c09e1c08', '2546e2aa-45eb-41aa-8969-1848a3cf454d', 1, 'Recognize that HCC/chronic-condition coding for a SPECIFIC encounter should reflect what was actually addressed/relevant to THAT encounter, not automatically import every condition from a different provider''s separate record — cross-encounter ''diagnosis carry-forward'' without current-encounter relevance is a recognized documentation-integrity and compliance risk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29098fbe-9ed4-492d-9204-e737ab4bb881', '2546e2aa-45eb-41aa-8969-1848a3cf454d', 2, 'Only the specialist''s own historical conditions may ever be coded, never anything from primary care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c388b86-8140-4f45-bb30-cc2485e78309', '2546e2aa-45eb-41aa-8969-1848a3cf454d', 3, 'Specialist encounters can never have any HCC-relevant diagnoses coded under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('733b2f21-d709-4041-90d4-05e258809303', '937d1f5c-dfd1-4c7c-b8b6-8e93cfe54b5b', 0, 'Automatically coding ESRD without any further consideration, since it''s mentioned in a note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50cc240a-6fe6-403b-8bfb-cbd61466e863', '937d1f5c-dfd1-4c7c-b8b6-8e93cfe54b5b', 1, 'Recognizing that a physician''s own note referencing and adopting outside information (even if originally from another source) can support coding IF the physician''s documentation reflects their own clinical acknowledgment/adoption of that information as part of the current assessment — the key is whether the treating physician has incorporated it into their own clinical picture, not merely whether it originated elsewhere');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19d9ab05-d465-48db-aae4-043146d56825', '937d1f5c-dfd1-4c7c-b8b6-8e93cfe54b5b', 2, 'Never coding any condition that was ever referenced as coming from an outside source');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fea28adb-f4df-4f9f-a88e-95dd8862a06d', '937d1f5c-dfd1-4c7c-b8b6-8e93cfe54b5b', 3, 'Requiring an outside facility''s dialysis records to be physically present in the chart before ESRD may ever be coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01b80e9d-12a0-42e7-abcf-c985a5d02250', '81147220-bf9c-40a8-ab90-352c36752692', 0, 'The operative/procedure report or device/implant log must specifically document the stent type used, since this device characteristic directly affects code/device-value selection and cannot be assumed by default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cb1db81-5b39-43c4-9acb-d1acf7c017be', '81147220-bf9c-40a8-ab90-352c36752692', 1, 'Device type is never a coding consideration for stent placement procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('121aa095-6b5f-4dcf-9334-444746791e30', '81147220-bf9c-40a8-ab90-352c36752692', 2, 'All stents are assumed to be drug-eluting by default unless documented otherwise');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e08eab33-0f56-4fab-9c83-6f63dc7291c8', '81147220-bf9c-40a8-ab90-352c36752692', 3, 'Device value specificity is optional and coder discretion governs regardless of documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bef26f05-09e1-474c-82f8-6951b0fe1115', 'd3e5129b-2b60-4ad2-a589-5eef144c9844', 0, 'Assume laparoscopic approach by default for that surgeon going forward without further verification each time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a31b5a8b-c8a6-482c-aebf-7a814057e6ab', 'd3e5129b-2b60-4ad2-a589-5eef144c9844', 1, 'Recognize this as a recurring, surgeon-specific documentation gap warranting both individual case-level query/verification and broader physician documentation education/feedback (a systemic pattern, not just a one-off missing detail), rather than either guessing a default approach or repeatedly querying without addressing the root cause');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c27556ad-e296-4047-b0a6-21882a1951d8', 'd3e5129b-2b60-4ad2-a589-5eef144c9844', 2, 'Ignore the pattern since surgery schedules aren''t official clinical documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb3912f1-ff15-45b9-a6fa-5120ad03bae3', 'd3e5129b-2b60-4ad2-a589-5eef144c9844', 3, 'Refuse to code any of that surgeon''s cases indefinitely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('163c0c24-6d93-4577-b42c-bd024587b958', 'ccc53ef9-38ad-4444-949d-4f012bc6910e', 0, 'Adequate documentation requiring no further review, since ''infection, resolved'' is sufficient for any coding purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b646f547-8d46-40df-9886-2fecd7ebc8ef', 'ccc53ef9-38ad-4444-949d-4f012bc6910e', 1, 'A specificity gap — the discharge summary''s vague closing characterization doesn''t resolve which specific diagnosis (if a specific source was ever actually confirmed) should be coded, warranting further review of the full course of the stay and/or a query to clarify the physician''s final determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63d847cc-cb42-4e15-badd-acdf4ea98f39', 'ccc53ef9-38ad-4444-949d-4f012bc6910e', 2, 'Grounds to automatically code both UTI and pneumonia as confirmed diagnoses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de96e454-d0e4-4fed-bf60-c619895b22f9', 'ccc53ef9-38ad-4444-949d-4f012bc6910e', 3, 'Grounds to code only ''sepsis'' as the final diagnosis regardless of what the record shows');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aceb86da-0f47-4cb4-b095-925df797e5a3', 'b9e9249a-7ae1-439f-a1fd-ae9dd4f35105', 0, 'Each unit''s documentation is treated as an entirely separate, unrelated encounter for coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ef9036c-5d76-4963-b74d-cf7600792896', 'b9e9249a-7ae1-439f-a1fd-ae9dd4f35105', 1, 'The patient''s diagnoses/status should be tracked consistently across the full continuum of the single inpatient stay, with transfer-related notes reviewed to ensure no relevant diagnosis, complication, or status change occurring around the transfer point is lost between documentation sources');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b458ac7-c712-4798-a827-3e020023954a', 'b9e9249a-7ae1-439f-a1fd-ae9dd4f35105', 2, 'Only the ICU documentation is ever used for coding, regardless of what happens after transfer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('738755a7-a928-4f22-a321-17c84d7368d0', 'b9e9249a-7ae1-439f-a1fd-ae9dd4f35105', 3, 'Unit transfers automatically trigger a new principal diagnosis determination');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c2be6a6-4069-47d9-90b5-c65b3dba6128', '26ad3843-cc13-4295-8934-58117ad661cc', 0, 'The templated/autotext language should always be trusted over free-text physician additions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b93d4081-b6e5-4a62-9468-1887803f6186', '26ad3843-cc13-4295-8934-58117ad661cc', 1, 'The physician''s own specific free-text documentation of the actual abnormal finding is generally more reliable than a generic autotext/template phrase that may not have been individually verified for this specific encounter — a recognized EHR documentation-quality risk (template/autotext over-generation) discussed as part of Domain 5''s data-integrity concepts as well');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0e77e57-ab2b-4f28-8f85-585f4f461cca', '26ad3843-cc13-4295-8934-58117ad661cc', 2, 'Both are equally unreliable and neither may be used for coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9122b3e8-9ac2-40c4-91dd-4f976175f7d7', '26ad3843-cc13-4295-8934-58117ad661cc', 3, 'The conflict must always be resolved by deleting the entire note');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47dfb538-8cfd-4f26-8a25-c45a2f637622', '90c5b28a-b8fc-4f70-a1a2-70e70b49f8db', 0, 'Any pressure ulcer identified at any point during the stay is automatically coded as hospital-acquired regardless of admission-time skin assessment documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('90245f5b-483a-4cf8-9abe-34348c908cf3', '90c5b28a-b8fc-4f70-a1a2-70e70b49f8db', 1, 'A thorough admission-time skin assessment (ideally within the first 24 hours) documenting the absence of the ulcer (or a different/lesser stage) is the key evidence supporting a genuinely hospital-acquired (POA=N) determination — without that admission-time baseline, distinguishing a truly hospital-acquired ulcer from one simply not caught/documented at admission becomes genuinely difficult');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea3251d9-35b3-46ce-a40b-dd4f4d2ed497', '90c5b28a-b8fc-4f70-a1a2-70e70b49f8db', 2, 'POA status for pressure ulcers is determined solely by the day-of-stay a wound care consult occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('500a094d-f2e3-47c2-8325-ca43c46ebbc8', '90c5b28a-b8fc-4f70-a1a2-70e70b49f8db', 3, 'Pressure ulcers are exempt from POA reporting entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4be12a0-5436-4df6-a635-536d0b93227c', '7de0a67f-ab61-4c14-9433-cdea243b9547', 0, 'Documentation should support both the UTI diagnosis itself AND its association with an indwelling urinary catheter (including catheter presence/duration), since CAUTI-specific coding and HAC-program identification depend on that specific catheter-association documentation, not just a generic UTI diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98df5bde-5558-441f-9c52-f372720f41b1', '7de0a67f-ab61-4c14-9433-cdea243b9547', 1, 'CAUTI is coded identically to any other UTI with no catheter-related documentation ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e62b963-f7c6-42cd-b6b4-e24fc1b97eac', '7de0a67f-ab61-4c14-9433-cdea243b9547', 2, 'Catheter presence is tracked only by nursing, with zero relevance to coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfdfc99d-ffd9-4ace-bae8-47d52f596acd', '7de0a67f-ab61-4c14-9433-cdea243b9547', 3, 'CAUTI can never be identified as a POA=N hospital-acquired condition under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19f1264a-7927-4ca3-9fe6-079d300d56d0', 'e31b745b-9b55-45a9-a3b6-48b3a5015288', 0, 'No documentation concern, since medication lists are self-explanatory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('364ddd95-be5d-4367-a257-09bc1a29e544', 'e31b745b-9b55-45a9-a3b6-48b3a5015288', 1, 'A potential ''treatment without a stated diagnosis'' documentation gap (the same pattern discussed for the insulin/diabetes example) — the new medication suggests an underlying condition that should be documented and coded if clinically supported, warranting further chart review or a query rather than either ignoring the medication or assuming a specific diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f951b0b-d90e-449e-84d5-5e77c490cb4b', 'e31b745b-9b55-45a9-a3b6-48b3a5015288', 2, 'Grounds to automatically code atrial fibrillation without any further verification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a30bb399-e79e-479c-a07f-038579c99f01', 'e31b745b-9b55-45a9-a3b6-48b3a5015288', 3, 'A billing-only concern with no coding relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3b1b23b-dd02-4774-87ab-b22eaef8c60e', '3bfd1c33-6209-4a1e-bb44-5f7a5485e76b', 0, 'The first procedure performed chronologically during the stay is always the principal procedure, regardless of its purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('038595df-5edd-4fc2-ac8f-0f160131b6e3', '3bfd1c33-6209-4a1e-bb44-5f7a5485e76b', 1, 'Reviewing the operative documentation for ALL procedures performed during the stay to determine which one was performed for definitive treatment of the condition primarily responsible for the admission (the UHDDS principal procedure definition), rather than automatically defaulting to chronological order or the most invasive-sounding procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca7c73f9-2541-41c9-9eac-26ab14273ee1', '3bfd1c33-6209-4a1e-bb44-5f7a5485e76b', 2, 'Whichever procedure has the highest-weighted DRG code is automatically the principal procedure by definition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e2eeb35-0ecb-4430-b19e-517bd3c09172', '3bfd1c33-6209-4a1e-bb44-5f7a5485e76b', 3, 'Only surgical (not diagnostic) procedures are ever considered when multiple procedures occur');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f76712ce-305c-4284-8f86-7eb673ee939c', '85c09662-6687-40d4-8b9e-849b3fe00756', 0, 'A normal, unremarkable order set requiring no documentation follow-up');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f83392a-2612-4d4f-b2c3-df0d05d902a8', '85c09662-6687-40d4-8b9e-849b3fe00756', 1, 'Another example of the ''treatment/monitoring implies an undocumented diagnosis'' gap pattern — these specific orders suggest an underlying condition (e.g., heart failure, fluid overload) that should be clinically documented and coded if actually present, warranting further review or query rather than assumption');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32131444-934d-4910-9948-c7d773dde3e2', '85c09662-6687-40d4-8b9e-849b3fe00756', 2, 'Proof the patient definitely has heart failure requiring immediate coding as such');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cbb11a4-ef0b-4335-a9ae-a811382cca94', '85c09662-6687-40d4-8b9e-849b3fe00756', 3, 'Something relevant only to nursing care plans, with zero coding relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6609bea6-9e2e-48d7-a223-7146a3628ead', 'c48b23a1-bff3-46d9-a1c2-e49a5e68a804', 0, 'Problem lists are always perfectly maintained and require zero verification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d18f6a06-0b09-4b81-8360-0b5d41372c05', 'c48b23a1-bff3-46d9-a1c2-e49a5e68a804', 1, 'Problem list modules can become outdated (containing resolved conditions never removed, or missing newly diagnosed conditions not yet added) if not actively maintained by clinical staff, making the actual encounter-specific documentation (notes, orders, results for that visit) a more reliable primary source for what is currently active and relevant to THIS encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2afa058-b934-4702-9fe0-5825fd4914a7', 'c48b23a1-bff3-46d9-a1c2-e49a5e68a804', 2, 'Problem lists should never be consulted under any circumstance during coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('473d718f-9ebb-4573-94af-1f03896462ea', 'c48b23a1-bff3-46d9-a1c2-e49a5e68a804', 3, 'Problem list accuracy is guaranteed by EHR vendor certification requirements with no facility-level maintenance needed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b599f25a-54d0-4125-a6f7-95e0e83eb8ae', '0948b178-9f0a-4849-8fa7-56e80d668c22', 0, 'Ask the physician to simply confirm ''systolic heart failure'' as the diagnosis with only a yes/no option');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d88c89b-0647-4a03-9d02-2be8c435e393', '0948b178-9f0a-4849-8fa7-56e80d668c22', 1, 'Present the objective echo finding and ask the physician to clarify whether this represents an active clinical diagnosis (e.g., systolic heart failure) requiring treatment/management, offering multiple options including ''not clinically significant at this time'' or ''other,'' allowing independent clinical judgment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef56118c-255a-4fec-98af-1deb3929e440', '0948b178-9f0a-4849-8fa7-56e80d668c22', 2, 'Assume systolic heart failure is present and code it without querying, since the echo finding is objective');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1547073-68c0-461c-9267-97b7d41a8937', '0948b178-9f0a-4849-8fa7-56e80d668c22', 3, 'Avoid querying entirely and code only ''abnormal echocardiogram finding'' with no further follow-up ever');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b0e9b47-2f65-4b77-ae8a-bab16ece5ebf', '7106a163-86f8-4a39-ae87-b9961b6f3e6a', 0, 'It is fully compliant since referencing reimbursement helps the physician understand why the query matters');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c8a0633-6dda-4659-a26a-fd64625223ec', '7106a163-86f8-4a39-ae87-b9961b6f3e6a', 1, 'Explicitly framing a query around reimbursement/risk-score optimization (rather than clinical accuracy) risks the query being non-compliant/leading — a query should be framed around obtaining an accurate, clinically supported diagnosis, not around achieving a specific financial or risk-score outcome');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d445d349-9212-4cc1-9084-ee72db12413a', '7106a163-86f8-4a39-ae87-b9961b6f3e6a', 2, 'AKI can never be a valid query subject');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('339b247f-4a91-4066-b973-8ea7b66c75f2', '7106a163-86f8-4a39-ae87-b9961b6f3e6a', 3, 'Only surgical diagnoses may ever be queried, never medical diagnoses like AKI');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e2f453f-0483-4aba-8ca5-45ca38e65a45', '5f536415-858f-4e4e-a07c-52531db27d3f', 0, 'Override the physician''s response and code AKI anyway based on the coder''s own interpretation of the lab values');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fdcc147-36f9-4501-8a75-51de3bb15e7e', '5f536415-858f-4e4e-a07c-52531db27d3f', 1, 'Generally respect the physician''s documented clinical judgment as the qualified clinical decision-maker — the physician may have clinical context (e.g., baseline chronic kidney disease, dilutional effects) not apparent from the lab value in isolation — while a facility''s CDI/quality program may separately choose to review such patterns in aggregate for education purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84528aa8-c2d2-4d64-8089-ed48b7b9469b', '5f536415-858f-4e4e-a07c-52531db27d3f', 2, 'Refuse to finalize the encounter''s coding indefinitely until the physician changes their answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('970d84e9-d8a2-4c02-a1e6-ac060b027131', '5f536415-858f-4e4e-a07c-52531db27d3f', 3, 'Report the physician to a regulatory body immediately based on a single query response');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc32aabe-455d-4c49-860d-1323b8b8f6e3', '5159b233-06de-487e-9a3f-fb1ce74b4fa8', 0, 'Leading, because it lists specific etiologies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfc1e1c3-1bd8-4d1f-92d3-3a3162dd0b2f', '5159b233-06de-487e-9a3f-fb1ce74b4fa8', 1, 'Non-leading — it presents multiple genuine, clinically plausible etiology categories plus open-ended and ''not clinically significant'' options, allowing the physician to select or specify based on independent clinical judgment rather than being steered toward one predetermined answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68d203fc-fd59-4d69-9c15-a000fdfd2f62', '5159b233-06de-487e-9a3f-fb1ce74b4fa8', 2, 'Non-compliant because AKI etiology should never be queried');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('555a73f7-ba1c-468e-9e02-694bcd2b1e2c', '5159b233-06de-487e-9a3f-fb1ce74b4fa8', 3, 'Leading because option (e) exists');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b11624d-9712-480d-a536-c49370c8c84c', 'b15f41e2-80f7-4bbf-a58d-16759f1300a7', 0, 'Skip querying since HCC-relevant conditions should never be queried due to reimbursement sensitivity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a2961a0-0326-4617-ae30-de4501e8be97', 'b15f41e2-80f7-4bbf-a58d-16759f1300a7', 1, 'This is a legitimate, clinically-driven query opportunity like any other specificity gap — the HCC-relevance of the condition doesn''t change the compliance analysis; the query should still be constructed around the clinical ambiguity itself (which specific complication), non-leading, not around the reimbursement impact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cc81530-6d1f-4e23-a48f-6ec7fedc32b4', 'b15f41e2-80f7-4bbf-a58d-16759f1300a7', 2, 'Automatically code the most severe complication type without querying, since the condition is HCC-relevant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cba8169f-8784-4cb0-aef6-8b8a083fe434', 'b15f41e2-80f7-4bbf-a58d-16759f1300a7', 3, 'Query the patient directly instead of the physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('657b3334-4008-49c6-a32d-69f70e5dec54', '9229aec6-7feb-4657-808d-e5acf1823da6', 0, 'Interpret ''yes'' as confirming whichever option the coder personally believes is more likely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98688091-5028-44d4-8813-9997670e05f0', '9229aec6-7feb-4657-808d-e5acf1823da6', 1, 'Recognize the response as ambiguous/non-responsive to a multi-option query and follow up for genuine clarification (per organizational query-escalation policy), since ''yes'' alone doesn''t actually answer which specific option was intended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d324380-aa61-4b57-b2a1-68815c3092db', '9229aec6-7feb-4657-808d-e5acf1823da6', 2, 'Code both stroke and metabolic causes automatically since some answer was given');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cede3a9f-3281-4e23-aeca-e4fdb8fa6ebf', '9229aec6-7feb-4657-808d-e5acf1823da6', 3, 'Discard the query and code nothing, since any response was received');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a41906a2-7bc1-4c03-ba8a-59231c394e09', 'c42e1311-eb36-4451-85be-edd0b8e5f1bd', 0, 'Only attending physicians may ever be queried; NPs and other qualified non-physician practitioners can never be query recipients');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf4e255d-47d2-4bdd-ae2e-95e141658ea0', 'c42e1311-eb36-4451-85be-edd0b8e5f1bd', 1, 'A query may generally be directed to whichever qualified healthcare professional is clinically responsible for/knowledgeable about the specific documentation in question — including an NP or other qualified practitioner who personally evaluated the condition — not exclusively the attending physician in every case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3ef73e6-6eae-4bf1-8b5b-8364c58d5a4e', 'c42e1311-eb36-4451-85be-edd0b8e5f1bd', 2, 'Queries must always go through the hospital''s medical director personally, regardless of who documented the finding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6cc183a-9c9c-4d18-bde3-d70c124dcc66', 'c42e1311-eb36-4451-85be-edd0b8e5f1bd', 3, 'NPs may only receive queries about billing, never clinical documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5707c4e2-794f-43ab-a63e-034080049bfa', 'd3e2ed69-6566-454c-880b-bef5fafbe2f5', 0, 'A library is unnecessary since every query must be entirely improvised from scratch each time with no prior review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4623e748-19bf-4125-876c-08d45e4c0dd0', 'd3e2ed69-6566-454c-880b-bef5fafbe2f5', 1, 'A curated set of pre-vetted, non-leading query templates for common clinical scenarios (e.g., AKI etiology, heart failure type, malnutrition severity) that have been reviewed for compliance, used as a starting point that is still tailored to the specific patient''s actual clinical indicators for each individual query — not simply auto-populated without case-specific customization');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5e44625-9e1c-4d8b-a634-0a2c8190f686', 'd3e2ed69-6566-454c-880b-bef5fafbe2f5', 2, 'Query templates automatically make every query compliant regardless of how they are actually used or customized for the specific case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('754bad07-6342-4ede-a296-4fd614b845dd', 'd3e2ed69-6566-454c-880b-bef5fafbe2f5', 3, 'Templates are prohibited entirely under AHIMA/ACDIS query-practice guidance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('168715a1-52a7-4ff4-b9eb-dcd40fd17b30', '8d121169-4ef1-4f21-b7ad-4c40ffcbc7fc', 0, 'No escalation path should ever exist; coders/CDI staff must simply keep waiting indefinitely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c52978c-abb0-4e82-a481-fc3d8c876c5e', '8d121169-4ef1-4f21-b7ad-4c40ffcbc7fc', 1, 'A pattern of non-response is appropriately escalated through the organization''s defined channels (e.g., physician advisor, medical staff leadership, or CDI/HIM department leadership) as a systemic issue, rather than each individual coder handling it in isolation or the pattern going unaddressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84a1a5c7-dd7e-43ec-b799-5102d383234f', '8d121169-4ef1-4f21-b7ad-4c40ffcbc7fc', 2, 'The correct escalation is to code the most favorable diagnosis automatically after a set number of unanswered queries');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8671fe5c-5409-445a-b325-d1badf544af9', '8d121169-4ef1-4f21-b7ad-4c40ffcbc7fc', 3, 'Physicians who don''t respond to queries should be reported directly to state licensing boards as the first step');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d97bb19e-5cb8-477c-8264-45e4bc3a7b68', '906f8304-8d99-4074-a0cc-43f6773e0223', 0, 'Querying purely to pursue a higher-weighted outcome, without genuine clinical indicators supporting the queried condition, risks constituting ''query fishing'' — a compliance concern distinct from a legitimate, indicator-driven query that happens to also affect reimbursement/risk score as a byproduct of accurate coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('918673cd-2f6e-412e-82bb-8e3329a8cd68', '906f8304-8d99-4074-a0cc-43f6773e0223', 1, 'There is no meaningful distinction between querying based on genuine indicators versus querying purely for reimbursement impact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4cf8937b-e2e1-4527-aef9-6e6ba434ec51', '906f8304-8d99-4074-a0cc-43f6773e0223', 2, 'Reimbursement/risk-score impact should always be the primary factor driving whether to query, more important than genuine clinical indicators');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55590492-761c-4136-a9ae-06530ab260f1', '906f8304-8d99-4074-a0cc-43f6773e0223', 3, 'Only diagnoses that decrease reimbursement may ever be queried, to avoid any appearance of bias');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba5ac759-d776-4fbe-b4fb-c26a30df2ccc', 'de1018b1-cbc0-4b06-a576-c9a6d007fd07', 0, 'No documentation is needed; the presumption applies automatically to every admission regardless of physician expectation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ce90f02-6725-497d-b764-839d99c36368', 'de1018b1-cbc0-4b06-a576-c9a6d007fd07', 1, 'The physician''s expectation of a stay spanning two midnights, and the medical necessity for hospital-level care, should be reasonably supported by the documented clinical picture at the time of the admission decision — not simply asserted after the fact without contemporaneous clinical support');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a10bc403-0d0e-41be-bc49-be8c34581a79', 'de1018b1-cbc0-4b06-a576-c9a6d007fd07', 2, 'Two-midnight documentation requirements apply only to Medicaid patients, never Medicare');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d71ca51-deb9-44b7-a45b-37b34a8b2721', 'de1018b1-cbc0-4b06-a576-c9a6d007fd07', 3, 'The rule requires exactly two midnights with no flexibility for shorter or longer stays ever being separately justified');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc702319-ba5c-4a90-a1e3-896ec412495a', '6bf56b48-7991-49ba-a1a6-d3864e2216a7', 0, 'Risk-adjustment coding carries no unique compliance risks distinct from inpatient DRG coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11abe5af-43d4-4a67-9f64-42ef1e757f76', '6bf56b48-7991-49ba-a1a6-d3864e2216a7', 1, 'Risk-adjustment-specific risks include diagnosis ''upcoding'' or carrying forward HCC-relevant diagnoses without current-encounter clinical support, and CMS/OIG audit activity (including Risk Adjustment Data Validation, RADV, audits) specifically targeting unsupported HCC diagnosis capture in Medicare Advantage and similar programs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6aa36a24-46cd-4657-be93-d220c4db5d88', '6bf56b48-7991-49ba-a1a6-d3864e2216a7', 2, 'HCC-related compliance risk applies only to outpatient laboratory billing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('593d6d2d-8047-4609-8a5f-e1ea49e560ed', '6bf56b48-7991-49ba-a1a6-d3864e2216a7', 3, 'RADV audits apply exclusively to inpatient hospital claims, never physician/health-plan risk-adjustment submissions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('231df365-2c68-4136-884b-09e5d9c3e658', 'b1bb6da3-8dda-4cc7-a961-b52a75f96087', 0, 'Status changes require no specific documentation; the final billing status may be selected at the biller''s convenience regardless of the clinical/physician determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1def428e-7289-4fc1-8c55-0c26972db843', 'b1bb6da3-8dda-4cc7-a961-b52a75f96087', 1, 'The actual physician-ordered status change (with its own timing and clinical rationale documented) should drive UHDDS/coding treatment of the stay, since inaccurately representing the status change (e.g., billing the entire stay as inpatient when only a later portion was properly converted) misstates both clinical and regulatory reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df15708c-8057-49a9-86a9-c35a705ac935', 'b1bb6da3-8dda-4cc7-a961-b52a75f96087', 2, 'Status changes are never permitted once a patient is registered under an initial status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bafdf747-d288-45b0-bd9a-aa61fff31858', 'b1bb6da3-8dda-4cc7-a961-b52a75f96087', 3, 'Only the initial admission status matters; any later change during the same stay is coding-irrelevant');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4371c54f-29d8-4d88-afbb-f01c2ef15715', '702de995-e615-447f-a61d-7e73abb613f7', 0, 'No special auditing obligation exists beyond general DRG-focused compliance auditing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebaf562e-c24e-4e2a-918b-22561a313a78', '702de995-e615-447f-a61d-7e73abb613f7', 1, 'Given RADV audit exposure and the direct payment impact of HCC diagnoses, facilities/health plans generally should include HCC-specific accuracy auditing (verifying clinical support and current-encounter relevance for submitted HCC diagnoses) as part of a comprehensive compliance program, not relying solely on general inpatient-DRG-focused audit activities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc96f847-8f51-412a-ab02-e81e8f1213c1', '702de995-e615-447f-a61d-7e73abb613f7', 2, 'HCC auditing is solely the health plan''s responsibility with zero facility/provider-side compliance role');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d80088b2-3241-4a18-a38d-ca0b2103fa0f', '702de995-e615-447f-a61d-7e73abb613f7', 3, 'HCC-relevant diagnoses are self-auditing and require no human review process at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9aeecb89-9476-410b-87a4-8df530276880', 'ce03d074-3caf-4aec-8a54-08bf36c4e96e', 0, 'A CMS audit process (and, at the plan level, an OIG/CMS-driven process) verifying that HCC diagnosis codes submitted for risk-adjusted payment (e.g., Medicare Advantage) are actually supported by medical record documentation, with unsupported diagnoses potentially resulting in payment recoupment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6bf31c2a-9dfd-407e-9bac-594a7471ff37', 'ce03d074-3caf-4aec-8a54-08bf36c4e96e', 1, 'A one-time audit that occurred only during the initial rollout of ICD-10-CM and is no longer performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c889c54-14ad-42a7-8e20-769322f65b38', 'ce03d074-3caf-4aec-8a54-08bf36c4e96e', 2, 'An audit exclusively of inpatient DRG assignment, unrelated to any risk-adjustment methodology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0bae0065-fe4f-41f5-a41c-18fe1641e401', 'ce03d074-3caf-4aec-8a54-08bf36c4e96e', 3, 'A voluntary audit facilities may choose to skip entirely with no consequence');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f84dea33-0e90-4b92-8f67-1497962b4b9e', 'b4715369-c963-4b0f-8851-cc67ec05cac8', 0, 'Diagnosis dropping and affirmatively coding an unsupported diagnosis are equally improper and treated identically under compliance standards');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdec62d3-1687-4808-998b-a986cca64535', 'b4715369-c963-4b0f-8851-cc67ec05cac8', 1, 'A condition genuinely not addressed/evaluated at any encounter during the current year appropriately doesn''t carry forward into that year''s risk score under the annual-recapture design of risk-adjustment models — this is different from affirmatively documenting/coding a diagnosis that ISN''T actually supported by current clinical evidence, which IS a compliance concern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('274befab-0ba0-4507-ad8d-142977162f05', 'b4715369-c963-4b0f-8851-cc67ec05cac8', 2, 'Diagnosis dropping is illegal and must always be affirmatively corrected by coding the condition regardless of whether it was addressed that year');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c6fa51d-1125-4551-a27e-27db47897ce7', 'b4715369-c963-4b0f-8851-cc67ec05cac8', 3, 'Risk-adjustment models have no annual component; all HCCs are permanent regardless of any given year''s documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a972ae1-fa59-4e79-95f5-b0dcbe08fee6', '6b46c49d-f4bb-456c-8c7d-6e2f2d1aabf4', 0, 'Retrospective review of medical records to identify previously undocumented/uncoded HCC-relevant diagnoses that WERE genuinely addressed/supported during a prior encounter is a legitimate compliance-supportive practice, but affirmatively adding diagnoses not actually supported by the documentation of that specific encounter would not be appropriate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a69611b-fe92-4fbb-8481-408748fb8fee', '6b46c49d-f4bb-456c-8c7d-6e2f2d1aabf4', 1, 'Retrospective chart review is always improper regardless of what it finds');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab1600d9-8fe0-40dd-855c-0149e196a067', '6b46c49d-f4bb-456c-8c7d-6e2f2d1aabf4', 2, 'Chart review may add any diagnosis a reviewer believes is clinically likely, even without documentation support');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3e1b522-146c-4de6-b1b0-b83fd81346a5', '6b46c49d-f4bb-456c-8c7d-6e2f2d1aabf4', 3, 'Chart review applies only to future encounters, never past ones');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c754ea15-129a-4514-9fea-f319e6d87b76', '49ead933-fb08-4552-ab10-e6c8bb0f6f61', 0, 'This pattern has no compliance relevance and should never be reviewed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72aa9936-bfad-46a5-b1c7-611735aeabe2', '49ead933-fb08-4552-ab10-e6c8bb0f6f61', 1, 'Such a skewed pattern is a recognized internal-monitoring flag potentially indicating leading query construction or query-fishing, warranting review of that specialist''s actual query language/practice — not an automatic presumption of wrongdoing, but a legitimate signal worth investigating');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3940531-70b0-44be-9527-d62ee2faaa04', '49ead933-fb08-4552-ab10-e6c8bb0f6f61', 2, 'A 100% agreement rate is always proof of excellent CDI work with no further review warranted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c38ace0e-547b-4f87-89b5-9889aa6c66d6', '49ead933-fb08-4552-ab10-e6c8bb0f6f61', 3, 'Only physician response patterns matter; CDI specialist query construction is never itself subject to compliance review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('899d5429-33dd-4559-b6c9-3b379f300fe1', 'e56f56b1-34de-42b4-802f-402827568e78', 0, 'No specific documentation is needed; status may be changed retroactively in the billing system alone without any updated physician order/rationale');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1d4bf92-ae2c-4b9f-b7b7-807d53f20bcc', 'e56f56b1-34de-42b4-802f-402827568e78', 1, 'The conversion should be supported by a physician order (or equivalent) reflecting the updated clinical assessment/rationale for inpatient-level care at the time of the actual determination, since UHDDS/coding treatment of the stay should reflect the genuine clinical decision-making timeline, not simply a retroactive billing system change unsupported by contemporaneous physician documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88a370e5-6168-49e1-ab7a-9b5b34c748fb', 'e56f56b1-34de-42b4-802f-402827568e78', 2, 'Status conversions occurring after the first 24 hours are never permitted under any payer''s policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f44f13ce-3405-4e85-855c-f4b81378c775', 'e56f56b1-34de-42b4-802f-402827568e78', 3, 'Only the admitting physician (never a covering or attending physician) may ever order a status conversion');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e93fc0db-fc14-412a-811b-fe991c9a4c8e', '73a00681-0231-44ee-ae02-5b8618d13294', 0, 'A billing code used only for ambulance transport');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2e38127-c46a-4f16-9cc3-efbca31bcc05', '73a00681-0231-44ee-ae02-5b8618d13294', 1, 'A specific process allowing a hospital to change a patient''s status from inpatient to outpatient/observation when, upon internal utilization review BEFORE discharge, it''s determined the inpatient admission didn''t meet medical necessity criteria — governed by specific procedural requirements (physician concurrence, UR committee involvement, before discharge)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8e2b2bf-e2b3-4d59-9e37-86c2033c3f84', '73a00681-0231-44ee-ae02-5b8618d13294', 2, 'A code indicating a patient left against medical advice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('151cb165-8215-4dd2-8693-4543deeec219', '73a00681-0231-44ee-ae02-5b8618d13294', 3, 'A modifier used exclusively in the CPT Surgery section');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('41947ce4-00e4-498a-b4c1-00475254e018', '82d2ac45-b0ca-4aee-831e-e132c1b41455', 0, 'Self-disclosure guarantees complete immunity from any consequences whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed74327c-231d-47e7-9fda-5c4fc58ad8a7', '82d2ac45-b0ca-4aee-831e-e132c1b41455', 1, 'Voluntary, proactive self-disclosure (through CMS/OIG''s self-disclosure protocols) is generally viewed more favorably than a problem later discovered through external audit, and can result in more favorable resolution terms — reflecting the broader compliance-program principle that proactive identification/correction is preferable to concealment or inaction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d90df7eb-ce3b-4b53-a488-4a8164f02b6c', '82d2ac45-b0ca-4aee-831e-e132c1b41455', 2, 'Self-disclosure is legally prohibited and facilities should never do it under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0af8c99-a197-4750-b327-1ba786fa1125', '82d2ac45-b0ca-4aee-831e-e132c1b41455', 3, 'Self-disclosure applies only to billing errors under $100, with no relevance to larger issues');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96d22890-5e06-4881-8cc0-a666c5fc464b', 'b28f1f8d-2898-4aa6-b83f-78f746386eff', 0, 'Documenting the compliance program''s own activities is unnecessary busywork with no practical value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df50b611-060c-4b5f-adcd-56358e210133', 'b28f1f8d-2898-4aa6-b83f-78f746386eff', 1, 'Maintaining records of the compliance program''s actual training, auditing, and corrective-action activities provides evidence the program is genuinely operating (not merely existing on paper) — relevant both to internal effectiveness assessment and to demonstrating good-faith compliance efforts if the organization is ever subject to external review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6b9bdbb-3d8f-4214-b111-b3e070b98d93', 'b28f1f8d-2898-4aa6-b83f-78f746386eff', 2, 'Only the initial compliance policy document needs to exist; ongoing activity records serve no purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('492d39eb-5936-485c-a47d-a0b54f237349', 'b28f1f8d-2898-4aa6-b83f-78f746386eff', 3, 'Compliance program documentation is relevant only to for-profit hospitals, never nonprofit or government facilities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f02c52c-2790-4285-b7be-3ac63d3308be', '8be92071-3481-407f-bb4a-826b7f384c45', 0, 'Trending has no value beyond the immediate payment calculation for the current reporting period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20335e90-a025-43bf-ad5e-3e1bd119196f', '8be92071-3481-407f-bb4a-826b7f384c45', 1, 'Trending HAC/PSI rates over time can help identify genuine clinical quality/safety improvement opportunities (distinct from pure documentation/coding accuracy issues) as well as surface potential documentation or POA-assignment accuracy issues if a facility''s coded rates diverge significantly from its actual clinical experience');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a54259ff-391a-42eb-bb36-f447a3765c6b', '8be92071-3481-407f-bb4a-826b7f384c45', 2, 'HAC/PSI rates are static, single-point-in-time measures that cannot be meaningfully trended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cba0bb92-6f73-4282-ab89-6fe33384f7c2', '8be92071-3481-407f-bb4a-826b7f384c45', 3, 'Only external auditors, never the facility itself, have any legitimate reason to review HAC/PSI trends');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2dcbc2c-9be9-4eea-b8cf-33c57160f06f', 'ed09a2d0-2f19-4a8f-85a1-cc81008ad091', 0, 'Productivity metrics should always be structured to discourage any query activity, since queries slow down coding throughput');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bfcce52-5413-4ec4-b9d9-3bbda71d7ace', 'ed09a2d0-2f19-4a8f-85a1-cc81008ad091', 1, 'A well-designed compliance-supportive coding department should structure productivity expectations in a way that doesn''t create a perverse incentive to skip legitimate, necessary queries purely to hit a raw case-per-hour target — since discouraging appropriate query practice through productivity pressure undermines documentation/coding accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f445178-49d6-4d53-993a-5d0c386f3155', 'ed09a2d0-2f19-4a8f-85a1-cc81008ad091', 2, 'Productivity metrics and query practice are entirely unrelated with no interaction ever considered in compliance program design');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4de8255c-9065-4ed7-a83a-c041f8f9ec18', 'ed09a2d0-2f19-4a8f-85a1-cc81008ad091', 3, 'Only individual coders, never department leadership, bear responsibility for this balance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9092141-90b6-416c-96c0-366c21002ffc', '7c369d57-b902-49bd-897c-7f7f98fbccc0', 0, 'POA accuracy for these specific HAC-relevant condition types has direct payment and quality-reporting impact, making a focused audit a reasonable, targeted compliance activity rather than relying solely on general, unfocused coding audits to catch this specific risk area');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccaebc79-db27-4803-8a3c-23e14e440018', '7c369d57-b902-49bd-897c-7f7f98fbccc0', 1, 'POA indicators for these conditions are always 100% accurate by default and require no auditing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6bc6aef0-191c-4def-939b-d10bee678e33', '7c369d57-b902-49bd-897c-7f7f98fbccc0', 2, 'Focused audits are prohibited; only fully comprehensive, all-diagnosis audits are permitted under compliance program standards');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e711ce32-176c-4748-8401-8af9eec863b4', '7c369d57-b902-49bd-897c-7f7f98fbccc0', 3, 'POA accuracy has no connection to HAC-program payment consequences');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('075e9457-ab82-403f-ae4c-c1c593b4469a', 'e06334f0-ec2a-44bb-aa68-e29b62ee715e', 0, 'No such distinction or policy is necessary; anyone with system access should be able to both code and submit claims interchangeably');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b10750b-09a6-4175-8bf6-a1710a16c898', 'e06334f0-ec2a-44bb-aa68-e29b62ee715e', 1, 'Clearly defining and separating who may code versus who may authorize final claim submission supports internal control and accountability — helping ensure a claim isn''t submitted with codes that haven''t gone through the organization''s actual coding/QA process');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('467df149-007c-4b6d-801d-5204c456440c', 'e06334f0-ec2a-44bb-aa68-e29b62ee715e', 2, 'This separation-of-duties concept applies only to financial/accounting departments, never to HIM/coding/billing workflows');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d89bcb88-472c-468e-bc02-b0fe55d78f01', 'e06334f0-ec2a-44bb-aa68-e29b62ee715e', 3, 'Claim submission authorization is solely an IT system permission setting with no compliance-policy relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('819eee48-af69-4e6e-9980-8f41ced03c91', 'dfe41ed5-3f03-404c-87ba-ed270ab36ab6', 0, 'Only one of the two audit frameworks is ever relevant to any single coder''s actual work, so understanding both is unnecessary');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('332c7dbf-5390-4c0b-987b-37516684b662', 'dfe41ed5-3f03-404c-87ba-ed270ab36ab6', 1, 'As healthcare payment increasingly spans both traditional fee-for-service (RAC/CERT-relevant) and risk-adjusted/value-based models (RADV-relevant), a coder working across these contexts benefits from understanding both audit frameworks'' distinct focus areas and documentation-support requirements, rather than assuming a single compliance framework covers all payment/audit exposure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1aeb23f2-112f-4f64-bd2b-00404c8fcf69', 'dfe41ed5-3f03-404c-87ba-ed270ab36ab6', 2, 'RAC, CERT, and RADV are simply three different names for the exact same audit process');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('092eced2-418d-4333-a4c1-7ca535ddf68f', 'dfe41ed5-3f03-404c-87ba-ed270ab36ab6', 3, 'Compliance audit programs are entirely payer-internal matters with zero relevance to coding staff regardless of context');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a74e727e-c20f-43e8-86eb-1aafddda35a0', 'a7b8b251-3cf1-4098-8108-349c15c26a62', 0, 'Internal reconciliation has no value since only external RADV findings matter for compliance purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fcbb7436-79ce-4ed3-99b8-bd1c3d37ca3a', 'a7b8b251-3cf1-4098-8108-349c15c26a62', 1, 'Proactive internal reconciliation (essentially a facility''s own mini-RADV-style self-check) helps identify and correct unsupported HCC diagnoses BEFORE an external audit finds them, consistent with the broader self-disclosure/proactive-correction compliance principle already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69f47413-9e46-4240-82e3-de94f2527c6b', 'a7b8b251-3cf1-4098-8108-349c15c26a62', 2, 'Internal reconciliation is only appropriate after a facility has already failed an external RADV audit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('684652a2-1b23-48aa-a74a-c1d6c07768e3', 'a7b8b251-3cf1-4098-8108-349c15c26a62', 3, 'HCC diagnosis reconciliation is solely a health plan responsibility, with zero facility-side role appropriate');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce6c2a74-7161-4e25-a421-ddeb90676f56', 'b7460090-0160-4063-9dd8-d4eea7250179', 0, 'A system default is always acceptable and requires no oversight regardless of the actual clinical facts of each case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78b5ea35-77b0-4e80-bd32-8529a30ea51e', 'b7460090-0160-4063-9dd8-d4eea7250179', 1, 'System configurations that apply a blanket default POA value without requiring/prompting an actual case-specific clinical determination risk systematically misstating POA data (in either direction) at scale — a system-design compliance risk distinct from, but related to, the individual-case documentation-integrity concerns already discussed for POA accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e10b7dfc-5fb8-47bf-b2a6-4c99cc09630b', 'b7460090-0160-4063-9dd8-d4eea7250179', 2, 'POA indicators are never affected by system configuration, only by manual coder entry');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f2072c7-443c-4b35-b5f2-625b620c23f9', 'b7460090-0160-4063-9dd8-d4eea7250179', 3, 'System defaults for POA are required by CMS and cannot be questioned or reviewed by facility compliance staff');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa67d5c9-8de8-4287-9851-32131043bd1f', 'bdb91757-b365-4c5e-bf44-7d002d74808e', 0, 'Physician concurrence is not actually required for condition code 44; a UR nurse''s determination alone is always sufficient');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5112544b-7f35-46db-952f-7e89b337f26c', 'bdb91757-b365-4c5e-bf44-7d002d74808e', 1, 'CMS''s condition code 44 process specifically requires the physician''s agreement with the utilization review determination (documented before discharge), since a clinical status determination like this appropriately requires physician-level clinical judgment, not solely a nursing/UR administrative determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f442a72-a234-4f0a-a705-a8c79bc398de', 'bdb91757-b365-4c5e-bf44-7d002d74808e', 2, 'Physician concurrence is only needed for outpatient-to-inpatient conversions, never the reverse direction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebcc2319-5e5e-49c9-aee1-9b1b34b6c820', 'bdb91757-b365-4c5e-bf44-7d002d74808e', 3, 'Condition code 44 applies only to Medicaid patients, never Medicare');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4732f7d-8f76-486c-90e3-b6afc99b1611', '4d6570c2-7008-47da-9de9-32809947cf48', 0, 'A single software product sold by one specific vendor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28a0ae7b-2ab2-405a-99d6-efdad0e22ea7', '4d6570c2-7008-47da-9de9-32809947cf48', 1, 'A set of international standards for the exchange, integration, sharing, and retrieval of electronic health information, providing a common framework/language different systems can use to communicate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5650dec7-0e15-463b-b5f2-10f46869b41a', '4d6570c2-7008-47da-9de9-32809947cf48', 2, 'A government regulatory agency that licenses hospitals');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bea84ced-3a6b-457e-9c42-64040574f3fd', '4d6570c2-7008-47da-9de9-32809947cf48', 3, 'A billing code set that replaced CPT');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20590baa-a1a0-4d3a-bc66-1afb0d50d41a', 'b734f83d-0976-478d-aabd-d96bf9d52dd1', 0, 'An older, now-deprecated HL7 standard no longer in active use');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('496d8267-5651-4441-b6a4-9a484ebb1e11', 'b734f83d-0976-478d-aabd-d96bf9d52dd1', 1, 'A modern HL7 interoperability standard built on web-based technologies (using discrete ''resources'' representing clinical concepts like Patient, Observation, Condition) designed to make health data exchange more developer-friendly and API-based than some older HL7 messaging standards');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ea1a9a8-2e4f-4695-8544-fd0c4da6f962', 'b734f83d-0976-478d-aabd-d96bf9d52dd1', 2, 'A proprietary standard owned exclusively by a single EHR vendor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68b96e18-62e3-47bb-943f-f4f17646c277', 'b734f83d-0976-478d-aabd-d96bf9d52dd1', 3, 'A coding classification system that replaces ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a9f1cd2-3ecb-4472-8396-42bca6fa3a56', '4bac3191-cc16-49d8-855a-16e9824f67bf', 0, 'They have no relevance to HIM/coding whatsoever, being purely an IT department concern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('751095ff-9f14-45fc-b7ad-122eeb6f97e7', '4bac3191-cc16-49d8-855a-16e9824f67bf', 1, 'As health information increasingly flows between organizations via these standards, HIM/coding professionals need to understand both the opportunities (more complete external clinical data available for documentation/coding context) and the data-quality verification responsibilities (as discussed in Domain 2) that come with using externally-sourced, standards-exchanged data');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7b2d20a-a6b0-4b80-b111-380db026feb8', '4bac3191-cc16-49d8-855a-16e9824f67bf', 2, 'Interoperability standards eliminate the need for any human coding or HIM review entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1130f9a8-2b1c-4965-a410-e4befa0c2b21', '4bac3191-cc16-49d8-855a-16e9824f67bf', 3, 'HL7/FHIR apply only to laboratory data, never clinical documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3835a391-3c3c-467f-8ecb-b1259c409af4', 'd90857b4-969a-42c3-aead-af14abf2fb6c', 0, 'Phishing is a hardware failure requiring IT repair, unrelated to human behavior');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1505f932-c193-43d9-97be-7c09c8c85ac5', 'd90857b4-969a-42c3-aead-af14abf2fb6c', 1, 'Phishing is a social-engineering attack technique (e.g., a deceptive email attempting to trick a staff member into revealing credentials or clicking a malicious link) that exploits human behavior rather than a purely technical system flaw — making workforce security awareness training (an administrative safeguard under the Security Rule) a relevant countermeasure alongside technical controls');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bba9e522-7eb8-4da1-88eb-25e971d60ee2', 'd90857b4-969a-42c3-aead-af14abf2fb6c', 2, 'Phishing applies only to personal email accounts, never workplace systems');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce3cc95e-2b63-4d77-998a-250706366026', 'd90857b4-969a-42c3-aead-af14abf2fb6c', 3, 'Phishing has no connection to HIPAA Security Rule administrative safeguards');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2fdc745-482f-4f77-b34e-5d7ec13cffbb', '3ccd0d1e-e421-49c0-b0e0-d3c59b0f27e9', 0, 'A type of beneficial software that improves system performance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffdcb950-248d-4438-b725-384aa2783f65', '3ccd0d1e-e421-49c0-b0e0-d3c59b0f27e9', 1, 'Malicious software that encrypts an organization''s data/systems, rendering them inaccessible until a ransom is paid (or the organization recovers via backups), representing both a security incident and a potential HIPAA breach/availability concern directly relevant to Security Rule contingency planning (backup and disaster recovery) requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56cbc063-7240-4af4-8979-2cc284a77083', '3ccd0d1e-e421-49c0-b0e0-d3c59b0f27e9', 2, 'A billing term for delayed insurance reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07e0e09b-22cc-400b-aadb-fe7b1a10538b', '3ccd0d1e-e421-49c0-b0e0-d3c59b0f27e9', 3, 'A type of EHR software update');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5bb709b3-633a-418f-ad9a-dc358bec246d', '22bb84a8-bf15-46d5-beda-63eef270bfa5', 0, 'All staff, regardless of job role, should have identical, unrestricted access to every system and every patient record for efficiency');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2882e2b4-31d8-4f3f-aabd-d19566ad5048', '22bb84a8-bf15-46d5-beda-63eef270bfa5', 1, 'Role-based access control assigns system/data access permissions based on a staff member''s specific job function/need (e.g., coders accessing coding-relevant systems and records, without unrestricted access to unrelated departments'' data), operationalizing the ''minimum necessary'' principle at the technical/system level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf093845-3938-4ab6-af9e-023a6441d52c', '22bb84a8-bf15-46d5-beda-63eef270bfa5', 2, 'Access controls apply only to physicians, never to HIM/coding staff');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a598064-c643-45ea-892a-9a41d160c4c0', '22bb84a8-bf15-46d5-beda-63eef270bfa5', 3, 'Role-based access is a marketing term with no actual technical implementation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b3e7bb0-3bb5-43e7-9457-26fad55b0d13', '93677c34-a257-411e-9062-583ad36edc52', 0, 'A system requiring only a username, with no password ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('610d0f4a-90b9-4e54-95be-5df794f578c1', '93677c34-a257-411e-9062-583ad36edc52', 1, 'Requiring two or more independent verification factors (e.g., a password plus a one-time code sent to a registered device) before granting access to a system containing ePHI, reducing the risk that a single compromised credential (e.g., a phished password) alone grants unauthorized access');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a002397c-bf54-4d07-86e3-49cae18ae8eb', '93677c34-a257-411e-9062-583ad36edc52', 2, 'A feature that automatically shares login credentials across all staff to simplify access');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbd0ae8d-9e40-48fe-be7d-fb687c224a50', '93677c34-a257-411e-9062-583ad36edc52', 3, 'A safeguard that applies only to patient-facing portals, never to internal HIM/coding staff systems');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b688729c-c7e8-497b-bf03-d2f75d9d49ab', 'd2a10989-a8d3-4108-b68e-3977f7eb5333', 0, 'They are the same concept applied at different times of day');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86d8758f-8cbd-4327-9602-67b51e3103e0', 'd2a10989-a8d3-4108-b68e-3977f7eb5333', 1, 'Encryption at rest protects data stored on a device/server/database when not actively being transmitted, while encryption in transit protects data as it moves across a network (e.g., between a coder''s workstation and a remote server) — both are relevant technical safeguards addressing different points of potential exposure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10d764f3-1ccf-4760-a851-dc53559ceebc', 'd2a10989-a8d3-4108-b68e-3977f7eb5333', 2, 'Only encryption in transit is ever required by the Security Rule; encryption at rest is never relevant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2142ca73-0354-46cd-85dd-c4516e39f69f', 'd2a10989-a8d3-4108-b68e-3977f7eb5333', 3, 'Encryption at rest applies only to paper records');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef4c9e6a-7346-4a57-b65c-fa3d1add0f70', 'a5b038b9-da70-4577-9b78-7de9e072347f', 0, 'BAAs are unnecessary for software vendors, only for other healthcare providers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6734f0a0-0a49-4b60-9b8d-95a7f19cee62', 'a5b038b9-da70-4577-9b78-7de9e072347f', 1, 'A BAA is a required HIPAA contract establishing a vendor''s obligations to appropriately safeguard ePHI it accesses/processes on the covered entity''s behalf — a third-party encoder/CAC/interoperability vendor with ePHI access generally requires one');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bafa9071-b794-4d95-8508-de52c9da451d', 'a5b038b9-da70-4577-9b78-7de9e072347f', 2, 'BAAs apply only to billing companies, never to coding-support software vendors');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59d362e0-42aa-4603-92d7-7e0505ca0b81', 'a5b038b9-da70-4577-9b78-7de9e072347f', 3, 'A BAA replaces the need for the vendor to comply with the HIPAA Security Rule at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ceea202-6db4-46d8-9fa2-a951a81df18c', 'e27c4ab7-c909-4514-986b-2dacffafe688', 0, 'Cloud-based systems require no different compliance consideration than on-premises systems, since the Security Rule doesn''t distinguish deployment models');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cfbf9ef-15ee-4d5a-8352-d25390b2438f', 'e27c4ab7-c909-4514-986b-2dacffafe688', 1, 'Cloud deployment introduces additional considerations (vendor BAA obligations, data location/residency, vendor security posture, access control configuration) that should be evaluated as part of the organization''s risk analysis and vendor management process, alongside the same core Security Rule safeguard requirements that apply regardless of deployment model');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b89cf7eb-2780-4eac-ae15-2d1ba169c79e', 'e27c4ab7-c909-4514-986b-2dacffafe688', 2, 'Cloud-based systems are prohibited under HIPAA for any ePHI-touching HIM function');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('771f013e-234b-4e42-8ee3-ce212470e023', 'e27c4ab7-c909-4514-986b-2dacffafe688', 3, 'Only on-premises systems can ever be HIPAA-compliant');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
